FDeepRow UNestedDeepLibrary::GetDeepRow(int32 Key, bool& bFound)
{
    const FDeepRow* Found = FNestedDeep::Deep().FindByIndex(Key);

    bFound = Found != nullptr;

    // A copy, because Blueprint takes a struct by value and the row belongs to the table.
    // A default one when the key is not there, which is why bFound is not decoration.
    return Found != nullptr ? *Found : FDeepRow();
}

int32 UNestedDeepLibrary::GetDeepRowCount()
{
    return FNestedDeep::Deep().Records().Num();
}

FDeepRow UNestedDeepLibrary::GetDeepRowAt(int32 Position, bool& bFound)
{
    const TArray<FDeepRow>& Rows = FNestedDeep::Deep().Records();

    bFound = Rows.IsValidIndex(Position);

    return bFound ? Rows[Position] : FDeepRow();
}


